-- INACTIVE SUPPLEMENT. Install only after database-fence-reference.sql and
-- admission-history-reference.sql in an isolated qualification database.
-- Not a runtime migration, authentication mechanism or production authorization.
-- Digests bind a trusted server's external decision; SQLite cannot observe remote runtime freshness.
CREATE TABLE release_admission_bindings (
 operation_id TEXT PRIMARY KEY NOT NULL CHECK(typeof(operation_id)='text' AND instr(operation_id,char(0))=0 AND length(operation_id)=36 AND substr(operation_id,1,4)='pub-' AND substr(operation_id,5) NOT GLOB '*[^0-9a-f]*') REFERENCES release_admission_decisions(operation_id),
 channel TEXT NOT NULL CHECK(typeof(channel)='text' AND instr(channel,char(0))=0 AND length(channel)=34 AND substr(channel,1,14)='engine:engine-' AND substr(channel,15) NOT GLOB '*[^0-9a-f]*'), owner TEXT NOT NULL CHECK(typeof(owner)='text' AND length(owner) BETWEEN 1 AND 128 AND instr(owner,char(0))=0), epoch INTEGER NOT NULL CHECK(typeof(epoch)='integer' AND epoch BETWEEN 1 AND 9007199254740991), target_revision TEXT NOT NULL CHECK(typeof(target_revision)='text' AND instr(target_revision,char(0))=0 AND length(target_revision)=32 AND substr(target_revision,1,8)='content-' AND substr(target_revision,9) NOT GLOB '*[^0-9a-f]*'),
 target_digest TEXT NOT NULL CHECK(typeof(target_digest)='text' AND instr(target_digest,char(0))=0 AND length(target_digest)=64 AND target_digest NOT GLOB '*[^0-9a-f]*'), target_commit TEXT NOT NULL CHECK(typeof(target_commit)='text' AND instr(target_commit,char(0))=0 AND length(target_commit)=40 AND target_commit NOT GLOB '*[^0-9a-f]*'), expected_revision TEXT CHECK(expected_revision IS NULL OR (typeof(expected_revision)='text' AND instr(expected_revision,char(0))=0 AND length(expected_revision)=32 AND substr(expected_revision,1,8)='content-' AND substr(expected_revision,9) NOT GLOB '*[^0-9a-f]*')),
 expected_generation INTEGER NOT NULL CHECK(typeof(expected_generation)='integer' AND expected_generation BETWEEN 0 AND 9007199254740990), mode TEXT NOT NULL CHECK(typeof(mode)='text' AND mode IN ('publish','rollback','bootstrap')),
 evidence_set_sha256 TEXT NOT NULL CHECK(typeof(evidence_set_sha256)='text' AND instr(evidence_set_sha256,char(0))=0 AND length(evidence_set_sha256)=64 AND evidence_set_sha256 NOT GLOB '*[^0-9a-f]*'),
 policy_sha256 TEXT NOT NULL CHECK(typeof(policy_sha256)='text' AND instr(policy_sha256,char(0))=0 AND length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*'),
 runtime_snapshot_sha256 TEXT NOT NULL CHECK(typeof(runtime_snapshot_sha256)='text' AND instr(runtime_snapshot_sha256,char(0))=0 AND length(runtime_snapshot_sha256)=64 AND runtime_snapshot_sha256 NOT GLOB '*[^0-9a-f]*'),
 rollback_snapshot_sha256 TEXT NOT NULL CHECK(typeof(rollback_snapshot_sha256)='text' AND instr(rollback_snapshot_sha256,char(0))=0 AND length(rollback_snapshot_sha256)=64 AND rollback_snapshot_sha256 NOT GLOB '*[^0-9a-f]*')
);
CREATE TABLE release_admission_seals (
 operation_id TEXT PRIMARY KEY NOT NULL CHECK(typeof(operation_id)='text' AND instr(operation_id,char(0))=0 AND length(operation_id)=36 AND substr(operation_id,1,4)='pub-' AND substr(operation_id,5) NOT GLOB '*[^0-9a-f]*') REFERENCES release_admission_bindings(operation_id),
 owner TEXT NOT NULL CHECK(typeof(owner)='text' AND length(owner) BETWEEN 1 AND 128 AND instr(owner,char(0))=0), epoch INTEGER NOT NULL CHECK(typeof(epoch)='integer' AND epoch BETWEEN 1 AND 9007199254740991),
 evidence_set_sha256 TEXT NOT NULL CHECK(typeof(evidence_set_sha256)='text' AND instr(evidence_set_sha256,char(0))=0 AND length(evidence_set_sha256)=64 AND evidence_set_sha256 NOT GLOB '*[^0-9a-f]*'),policy_sha256 TEXT NOT NULL CHECK(typeof(policy_sha256)='text' AND instr(policy_sha256,char(0))=0 AND length(policy_sha256)=64 AND policy_sha256 NOT GLOB '*[^0-9a-f]*'),runtime_snapshot_sha256 TEXT NOT NULL CHECK(typeof(runtime_snapshot_sha256)='text' AND instr(runtime_snapshot_sha256,char(0))=0 AND length(runtime_snapshot_sha256)=64 AND runtime_snapshot_sha256 NOT GLOB '*[^0-9a-f]*'),rollback_snapshot_sha256 TEXT NOT NULL CHECK(typeof(rollback_snapshot_sha256)='text' AND instr(rollback_snapshot_sha256,char(0))=0 AND length(rollback_snapshot_sha256)=64 AND rollback_snapshot_sha256 NOT GLOB '*[^0-9a-f]*')
);
CREATE TRIGGER release_admission_bindings_update BEFORE UPDATE ON release_admission_bindings BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER release_admission_bindings_delete BEFORE DELETE ON release_admission_bindings BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER release_admission_bindings_replace BEFORE INSERT ON release_admission_bindings WHEN EXISTS(SELECT 1 FROM release_admission_bindings WHERE operation_id=NEW.operation_id OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER release_admission_seals_update BEFORE UPDATE ON release_admission_seals BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER release_admission_seals_delete BEFORE DELETE ON release_admission_seals BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER release_admission_seals_replace BEFORE INSERT ON release_admission_seals WHEN EXISTS(SELECT 1 FROM release_admission_seals WHERE operation_id=NEW.operation_id OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'immutable-admission-seal'); END;
CREATE TRIGGER admission_binding_identity BEFORE INSERT ON release_admission_bindings BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id
 WHERE a.operation_id IS NEW.operation_id AND a.channel IS NEW.channel AND a.owner IS NEW.owner AND a.epoch IS NEW.epoch AND a.target_revision IS NEW.target_revision AND a.target_digest IS NEW.target_digest AND a.target_commit IS NEW.target_commit AND a.expected_revision IS NEW.expected_revision AND a.expected_generation IS NEW.expected_generation AND a.mode IS NEW.mode AND d.operation_id IS NEW.operation_id AND d.channel IS NEW.channel AND d.owner IS NEW.owner AND d.epoch IS NEW.epoch AND d.target_revision IS NEW.target_revision AND d.target_digest IS NEW.target_digest AND d.target_commit IS NEW.target_commit AND d.expected_revision IS NEW.expected_revision AND d.expected_generation IS NEW.expected_generation AND d.mode IS NEW.mode AND a.state='preparing' AND a.stopped=0) THEN RAISE(ABORT,'binding-identity-rejected') END;
END;
CREATE TRIGGER admission_seal_guard BEFORE INSERT ON release_admission_seals BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id JOIN release_admission_bindings b ON b.operation_id=a.operation_id
 WHERE a.operation_id IS b.operation_id AND a.channel IS b.channel AND a.owner IS b.owner AND a.epoch IS b.epoch AND a.target_revision IS b.target_revision AND a.target_digest IS b.target_digest AND a.target_commit IS b.target_commit AND a.expected_revision IS b.expected_revision AND a.expected_generation IS b.expected_generation AND a.mode IS b.mode AND d.operation_id IS b.operation_id AND d.channel IS b.channel AND d.owner IS b.owner AND d.epoch IS b.epoch AND d.target_revision IS b.target_revision AND d.target_digest IS b.target_digest AND d.target_commit IS b.target_commit AND d.expected_revision IS b.expected_revision AND d.expected_generation IS b.expected_generation AND d.mode IS b.mode AND NEW.operation_id IS b.operation_id AND NEW.owner IS b.owner AND NEW.epoch IS b.epoch AND NEW.evidence_set_sha256 IS b.evidence_set_sha256 AND NEW.policy_sha256 IS b.policy_sha256 AND NEW.runtime_snapshot_sha256 IS b.runtime_snapshot_sha256 AND NEW.rollback_snapshot_sha256 IS b.rollback_snapshot_sha256 AND a.state='preparing' AND a.stopped=0 AND COALESCE((SELECT MAX(e.generation) FROM content_publication_events e WHERE e.channel=a.channel),0)=a.expected_generation
 AND ((a.mode='bootstrap' AND a.expected_revision IS NULL AND a.expected_generation=0
       AND NOT EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel)
       AND NOT EXISTS(SELECT 1 FROM content_publication_events e WHERE e.channel=a.channel))
  OR (a.mode IN ('publish','rollback') AND a.expected_revision IS NOT NULL
       AND EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel AND p.revision_id=a.expected_revision)))
 AND EXISTS(SELECT 1 FROM content_revisions r JOIN content_publication_provenance pr ON pr.revision_id=r.id
 WHERE r.id=a.target_revision AND r.completed=1 AND r.digest=a.target_digest AND a.channel='engine:'||r.engine
 AND pr.commit_sha=a.target_commit AND pr.repository='LeiterConsulting/splunk-version-value-explorer')) THEN RAISE(ABORT,'admission-seal-rejected') END;
END;
CREATE TRIGGER admission_transition_requires_seal BEFORE UPDATE ON release_admission WHEN NEW.state='admitted' AND OLD.state!='admitted' BEGIN
 SELECT CASE WHEN OLD.state!='preparing' OR NEW.stopped!=0 OR OLD.stopped!=0 OR NOT EXISTS(
 SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id JOIN release_admission_bindings b ON b.operation_id=a.operation_id JOIN release_admission_seals s ON s.operation_id=a.operation_id
 WHERE a.operation_id IS b.operation_id AND a.channel IS b.channel AND a.owner IS b.owner AND a.epoch IS b.epoch AND a.target_revision IS b.target_revision AND a.target_digest IS b.target_digest AND a.target_commit IS b.target_commit AND a.expected_revision IS b.expected_revision AND a.expected_generation IS b.expected_generation AND a.mode IS b.mode AND d.operation_id IS b.operation_id AND d.channel IS b.channel AND d.owner IS b.owner AND d.epoch IS b.epoch AND d.target_revision IS b.target_revision AND d.target_digest IS b.target_digest AND d.target_commit IS b.target_commit AND d.expected_revision IS b.expected_revision AND d.expected_generation IS b.expected_generation AND d.mode IS b.mode AND s.operation_id IS b.operation_id AND s.owner IS b.owner AND s.epoch IS b.epoch AND s.evidence_set_sha256 IS b.evidence_set_sha256 AND s.policy_sha256 IS b.policy_sha256 AND s.runtime_snapshot_sha256 IS b.runtime_snapshot_sha256 AND s.rollback_snapshot_sha256 IS b.rollback_snapshot_sha256 AND NEW.operation_id IS b.operation_id AND NEW.channel IS b.channel AND NEW.owner IS b.owner AND NEW.epoch IS b.epoch AND NEW.target_revision IS b.target_revision AND NEW.target_digest IS b.target_digest AND NEW.target_commit IS b.target_commit AND NEW.expected_revision IS b.expected_revision AND NEW.expected_generation IS b.expected_generation AND NEW.mode IS b.mode AND a.state='preparing' AND a.stopped=0 AND COALESCE((SELECT MAX(e.generation) FROM content_publication_events e WHERE e.channel=a.channel),0)=a.expected_generation
 AND ((a.mode='bootstrap' AND a.expected_revision IS NULL AND a.expected_generation=0
       AND NOT EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel)
       AND NOT EXISTS(SELECT 1 FROM content_publication_events e WHERE e.channel=a.channel))
  OR (a.mode IN ('publish','rollback') AND a.expected_revision IS NOT NULL
       AND EXISTS(SELECT 1 FROM content_publication p WHERE p.channel=a.channel AND p.revision_id=a.expected_revision)))
 AND EXISTS(SELECT 1 FROM content_revisions r JOIN content_publication_provenance pr ON pr.revision_id=r.id
 WHERE r.id=a.target_revision AND r.completed=1 AND r.digest=a.target_digest AND a.channel='engine:'||r.engine
 AND pr.commit_sha=a.target_commit AND pr.repository='LeiterConsulting/splunk-version-value-explorer')) THEN RAISE(ABORT,'admission-seal-required') END;
END;
CREATE TRIGGER admission_seal_apply AFTER INSERT ON release_admission_seals BEGIN
 UPDATE release_admission SET state='admitted' WHERE operation_id=NEW.operation_id AND owner=NEW.owner AND epoch=NEW.epoch AND state='preparing' AND stopped=0;
 SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'admission-seal-transition-failed') END;
END;
-- Legacy admitted observations are not grandfathered into write authority.
CREATE TRIGGER publication_requires_admission_seal BEFORE INSERT ON content_publication_events BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id JOIN release_admission_bindings b ON b.operation_id=a.operation_id JOIN release_admission_seals s ON s.operation_id=a.operation_id
 WHERE a.operation_id IS b.operation_id AND a.channel IS b.channel AND a.owner IS b.owner AND a.epoch IS b.epoch AND a.target_revision IS b.target_revision AND a.target_digest IS b.target_digest AND a.target_commit IS b.target_commit AND a.expected_revision IS b.expected_revision AND a.expected_generation IS b.expected_generation AND a.mode IS b.mode AND d.operation_id IS b.operation_id AND d.channel IS b.channel AND d.owner IS b.owner AND d.epoch IS b.epoch AND d.target_revision IS b.target_revision AND d.target_digest IS b.target_digest AND d.target_commit IS b.target_commit AND d.expected_revision IS b.expected_revision AND d.expected_generation IS b.expected_generation AND d.mode IS b.mode AND s.operation_id IS b.operation_id AND s.owner IS b.owner AND s.epoch IS b.epoch AND s.evidence_set_sha256 IS b.evidence_set_sha256 AND s.policy_sha256 IS b.policy_sha256 AND s.runtime_snapshot_sha256 IS b.runtime_snapshot_sha256 AND s.rollback_snapshot_sha256 IS b.rollback_snapshot_sha256 AND a.operation_id=NEW.operation_id AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.operation_id=NEW.writer_operation AND a.state='admitted' AND a.stopped=0)
 THEN RAISE(ABORT,'publication-seal-required') END;
END;

-- Head writes must not consume a preexisting unsealed legacy event.
CREATE TRIGGER head_insert_requires_admission_seal BEFORE INSERT ON content_publication BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id JOIN release_admission_bindings b ON b.operation_id=a.operation_id JOIN release_admission_seals s ON s.operation_id=a.operation_id
 WHERE a.operation_id IS b.operation_id AND a.channel IS b.channel AND a.owner IS b.owner AND a.epoch IS b.epoch AND a.target_revision IS b.target_revision AND a.target_digest IS b.target_digest AND a.target_commit IS b.target_commit AND a.expected_revision IS b.expected_revision AND a.expected_generation IS b.expected_generation AND a.mode IS b.mode AND d.operation_id IS b.operation_id AND d.channel IS b.channel AND d.owner IS b.owner AND d.epoch IS b.epoch AND d.target_revision IS b.target_revision AND d.target_digest IS b.target_digest AND d.target_commit IS b.target_commit AND d.expected_revision IS b.expected_revision AND d.expected_generation IS b.expected_generation AND d.mode IS b.mode AND s.operation_id IS b.operation_id AND s.owner IS b.owner AND s.epoch IS b.epoch AND s.evidence_set_sha256 IS b.evidence_set_sha256 AND s.policy_sha256 IS b.policy_sha256 AND s.runtime_snapshot_sha256 IS b.runtime_snapshot_sha256 AND s.rollback_snapshot_sha256 IS b.rollback_snapshot_sha256 AND a.channel=NEW.channel AND a.target_revision=NEW.revision_id AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.operation_id=NEW.writer_operation AND a.state='admitted' AND a.stopped=0)
 THEN RAISE(ABORT,'publication-seal-required') END;
END;

-- Head writes must not consume a preexisting unsealed legacy event.
CREATE TRIGGER head_update_requires_admission_seal BEFORE UPDATE ON content_publication BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM release_admission a JOIN release_admission_decisions d ON d.operation_id=a.operation_id JOIN release_admission_bindings b ON b.operation_id=a.operation_id JOIN release_admission_seals s ON s.operation_id=a.operation_id
 WHERE a.operation_id IS b.operation_id AND a.channel IS b.channel AND a.owner IS b.owner AND a.epoch IS b.epoch AND a.target_revision IS b.target_revision AND a.target_digest IS b.target_digest AND a.target_commit IS b.target_commit AND a.expected_revision IS b.expected_revision AND a.expected_generation IS b.expected_generation AND a.mode IS b.mode AND d.operation_id IS b.operation_id AND d.channel IS b.channel AND d.owner IS b.owner AND d.epoch IS b.epoch AND d.target_revision IS b.target_revision AND d.target_digest IS b.target_digest AND d.target_commit IS b.target_commit AND d.expected_revision IS b.expected_revision AND d.expected_generation IS b.expected_generation AND d.mode IS b.mode AND s.operation_id IS b.operation_id AND s.owner IS b.owner AND s.epoch IS b.epoch AND s.evidence_set_sha256 IS b.evidence_set_sha256 AND s.policy_sha256 IS b.policy_sha256 AND s.runtime_snapshot_sha256 IS b.runtime_snapshot_sha256 AND s.rollback_snapshot_sha256 IS b.rollback_snapshot_sha256 AND a.channel=NEW.channel AND a.target_revision=NEW.revision_id AND a.owner=NEW.writer_owner AND a.epoch=NEW.writer_epoch AND a.operation_id=NEW.writer_operation AND a.state='admitted' AND a.stopped=0)
 THEN RAISE(ABORT,'publication-seal-required') END;
END;
